after.calc.py:
def add(a, b):
    return a + b


def divide(a, b):
    if b == 0:
        raise ValueError("b must not be zero")
    return a / b

after.tests/test_calc.py:
import pytest
from calc import add, divide


def test_add():
    assert add(2, 3) == 5


def test_divide():
    assert divide(6, 3) == 2


def test_divide_by_zero():
    with pytest.raises(ValueError):
        divide(1, 0)
